  "track.debugging.m.inspect.diagramDesc": "Database Inspector đọc và sửa bảng của app đang chạy; Background Task Inspector đọc trạng thái các worker",
  "track.debugging.m.inspect.n.app": "App đang chạy",
  "track.debugging.m.inspect.n.db": "Cơ sở dữ liệu (Room)",
